-- parent_advice (saran ortu) — DDL + seed 70 baris
-- rating sudah dinormalisasi: Semua Umur/3+ -> SU, 7+ ->7+, 13+ ->13+, 15+ ->17+, 18+ ->PRC

CREATE TABLE IF NOT EXISTS parent_advice (
    id     SERIAL PRIMARY KEY,
    rating VARCHAR(10) NOT NULL,
    saran  TEXT        NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_parent_advice_rating ON parent_advice (rating);

