INSERT INTO parent_advice (rating, saran) VALUES
  ('SU', 'Tingkatkan Kesadaran Digital Keamanan Dasar: Orang tua perlu memahami pilar Digital Safety (Keamanan Digital) untuk mengenali risiko yang ada di internet sebelum melepaskan anak ke dunia maya.'),
  ('SU', 'Terapkan Pola Asuh yang Proaktif dan Adaptif: Terapkan gaya pengasuhan yang terbuka, di mana orang tua memposisikan diri sebagai pembimbing, bukan sekadar pengawas yang mengekang.'),
  ('SU', 'Ciptakan Lingkungan Pengasuhan yang Aman: Pastikan rumah menjadi ''Taman Asuh'' yang ramah, di mana anak merasa aman secara emosional untuk bercerita jika mereka melihat sesuatu yang mengganggu di internet.'),
  ('SU', 'Terus Perbarui Pengetahuan Tren Digital: Internet terus berkembang. Orang tua perlu membaca dan mengikuti Peta Jalan Perlindungan Anak di Internet agar selalu up-to-date dengan ancaman gaya baru.'),
  ('SU', 'Bangun Komunikasi Tanpa Penghakiman: Jika anak melakukan kesalahan di ruang digital (misalnya mengakses konten yang tidak pantas), diskusikan dampaknya secara tenang agar mereka tidak takut untuk melapor di kemudian hari.'),
  ('SU', 'Terapkan Batasan Waktu Layar Berdasarkan Usia: Gunakan panduan rentang usia (0-18 tahun) untuk menentukan durasi maksimal menatap layar agar tidak mengganggu perkembangan kognitif dan motorik anak.'),
  ('SU', 'Pilih Perangkat Sesuai Kesiapan Mental: Jangan terburu-buru memberikan gawai pribadi. Berikan akses internet secara bertahap sesuai dengan tingkat kematangan emosional anak.'),
  ('SU', 'Dampingi Penuh untuk Anak Usia Dini: Untuk anak balita hingga usia prasekolah, penggunaan gawai harus 100% didampingi (co-viewing) dan diarahkan pada konten yang edukatif.'),
  ('SU', 'Gunakan Fitur Parental Control: Aktifkan fitur pembatasan usia, mode aman (safe search), dan kontrol privasi pada semua perangkat gawai maupun jaringan Wi-Fi di rumah.'),
  ('SU', 'Buat ''Zona Bebas Gawai'' di Rumah: Tetapkan aturan area tanpa gawai, seperti di ruang makan atau kamar tidur, untuk menjaga interaksi sosial dunia nyata dan kualitas tidur anak.'),
  ('SU', 'Edukasi Pentingnya Privasi Data: Ajarkan anak untuk tidak pernah membagikan informasi pribadi (nama lengkap, alamat, nama sekolah, nomor telepon) di media sosial atau game online.'),
  ('SU', 'Ajarkan Pembuatan Kata Sandi yang Kuat: Latih anak untuk membuat password yang aman, tidak mudah ditebak, dan tidak membagikannya kepada siapa pun, termasuk teman dekatnya.'),
  ('SU', 'Lakukan Evaluasi Kesadaran Siber Mandiri: Gunakan instrumen seperti SKKS untuk mengecek sejauh mana keluarga sudah menerapkan praktik kebersihan siber (cyber hygiene) secara rutin.'),
  ('SU', 'Waspadai Social Engineering: Beritahu anak tentang bahaya manipulasi psikologis di internet, seperti orang asing di game online yang berpura-pura menjadi teman sebaya untuk meminta data diri.'),
  ('SU', 'Saring Teman di Dunia Maya: Ajarkan anak untuk hanya menerima permintaan pertemanan dari orang-orang yang benar-benar mereka kenal di dunia nyata.'),
  ('SU', 'Edukasi Anatomi dan Batasan Sentuhan Digital: Ajarkan bahwa tubuh mereka adalah otoritas mereka, dan tidak ada yang boleh meminta foto/video bagian tubuh pribadi dengan alasan apa pun.'),
  ('SU', 'Kenali Tanda-tanda Grooming (Manipulasi Predator): Edukasi anak mengenai ciri-ciri predator online yang mencoba membangun kedekatan emosional (memberikan hadiah/item game) untuk tujuan eksploitasi.'),
  ('SU', 'Latih Sikap Asertif Menghadapi Cyberbullying: Ajarkan anak cara memblokir (block), melaporkan (report), dan mengabaikan pesan dari pelaku perundungan siber, serta menyimpannya sebagai bukti jika perlu.'),
  ('SU', 'Sinkronisasi Literasi dengan Sekolah: Berkolaborasi dengan guru di sekolah dasar untuk memastikan nilai-nilai keamanan digital yang diajarkan di kelas sejalan dengan praktik di rumah.'),
  ('SU', 'Simpan Kontak Layanan Perlindungan Anak (LPLPA): Orang tua harus tahu ke mana harus melapor. Simpan nomor telepon lembaga penyedia layanan terdekat (seperti SAPA 129) sebagai langkah mitigasi jika terjadi keadaan darurat atau kekerasan di ruang digital.'),
  ('SU', 'Pendampingan Penuh (100% Co-viewing): Jangan biarkan anak menatap layar sendirian; orang tua harus selalu menemani dan berinteraksi saat konten diputar.'),
  ('SU', 'Batasan Screentime Ekstra Ketat: Batasi waktu layar maksimal 1 jam per hari, dan pastikan hanya untuk konten edukasi yang berkualitas.'),
  ('SU', 'Gunakan Ekosistem Khusus Anak: Instal hanya aplikasi berating balita (misal: YouTube Kids) dan nonaktifkan fitur putar otomatis (autoplay).'),
  ('SU', 'Kunci Pembelian Aplikasi: Aktifkan PIN atau pengaman sidik jari untuk mencegah anak tidak sengaja mengklik iklan atau melakukan in-app purchases.'),
  ('SU', 'Aktifkan SafeSearch: Pastikan mode pencarian aman terkunci di semua peramban (browser) yang ada di perangkat rumah.'),
  ('SU', 'Hindari Gawai sebagai ''Pengasuh'': Jangan biasakan memberikan gawai sebagai jalan pintas untuk menenangkan anak yang sedang rewel atau tantrum.'),
  ('SU', 'Jauhkan dari Area Vital: Ciptakan zona bebas gawai di rumah, terutama di meja makan dan di dalam kamar tidur anak.'),
  ('SU', 'Edukasi Kepemilikan Dasar: Ajarkan konsep sederhana bahwa gawai adalah milik orang tua yang ''dipinjamkan'', sehingga orang tua berhak mengambilnya kapan saja.'),
  ('SU', 'Gunakan Mode Pesawat/Luring: Jika anak bermain game edukasi, matikan internet untuk memblokir iklan pop-up yang tidak terduga.'),
  ('SU', 'Hindari Sharenting Berlebihan: Lindungi jejak digital anak Anda sejak dini dengan tidak mengunggah foto mereka saat sedang tidak berpakaian lengkap atau saat sedang menangis ke media sosial publik.'),
  ('7+', 'Buat Kontrak Digital Keluarga: Susun kesepakatan tertulis yang menyenangkan bersama anak mengenai kapan, di mana, dan berapa lama gawai boleh digunakan.'),
  ('7+', 'Aturan ''Berhenti, Tutup, Beritahu'': Latih anak agar segera menutup layar dan melapor ke orang tua jika melihat gambar/video yang membuat mereka takut atau tidak nyaman.'),
  ('7+', 'Proteksi Data Pribadi Dasar: Ajarkan larangan keras membagikan nama lengkap, nama sekolah, umur, atau alamat rumah di dalam game online.'),
  ('7+', 'Konsep Jejak Digital Pertama: Berikan analogi sederhana bahwa ''apa pun yang ditaruh di internet sama seperti menulis di dinding tembok dengan spidol permanen''.'),
  ('7+', 'Gunakan Parental Control Terpusat: Manfaatkan aplikasi seperti Google Family Link untuk memantau durasi, membatasi jam malam otomatis, dan menyaring aplikasi yang diunduh.'),
  ('7+', 'Ajarkan Etika Ketik (Netiket): Edukasi bahwa mengetik kata-kata kasar atau mengejek teman di chat game online sama buruknya dengan mengejek secara langsung.'),
  ('7+', 'Pembuatan Sandi Rahasia: Bantu anak membuat password yang aman dan tekankan bahwa password ibarat kunci rumah yang tidak boleh diberikan kepada siapa pun, bahkan sahabat sendiri.'),
  ('7+', 'Seleksi Pertemanan Digital: Tanamkan aturan untuk hanya menerima pertemanan di game atau aplikasi dari teman yang benar-benar mereka kenal di sekolah atau lingkungan rumah.'),
  ('7+', 'Kenalkan Konsep Manipulasi Iklan: Beri pemahaman cara membedakan mana tombol menu asli di dalam game dan mana tombol iklan yang menjebak.'),
  ('7+', 'Respon Tanpa Hukuman Fisik/Verbal: Jika anak tidak sengaja membuka konten terlarang, responlah dengan tenang agar mereka tidak takut untuk melapor di masa depan.'),
  ('13+', 'Edukasi Bahaya Grooming: Diskusikan ciri-ciri predator online yang mencoba mendekati remaja dengan memberikan hadiah (seperti skin/item game atau pulsa) untuk mendapatkan rasa percaya.'),
  ('13+', 'Kunci Privasi Akun: Tinjau pengaturan akun media sosial anak bersama-sama dan pastikan profilnya disetel ke mode privat/terkunci.'),
  ('13+', 'Latih Fitur Proteksi Mandiri: Ajarkan dan pastikan anak tahu cara menggunakan fitur Block (blokir), Mute (bisukan), dan Report (laporkan) di setiap platform.'),
  ('13+', 'Edukasi Anatomi Tubuh & Seksual Digital: Berikan pemahaman tegas tentang bahayanya mengirim foto atau video intim kepada siapa pun, termasuk pacar, karena rentan dijadikan alat pemerasan (sextortion).'),
  ('13+', 'Kelola FOMO (Fear of Missing Out): Diskusikan bahwa apa yang terlihat di media sosial teman-temannya hanyalah ''potongan terbaik'' (highlight reel) dari hidup mereka, bukan realitas sepenuhnya.'),
  ('13+', 'Literasi Anti-Hoax: Latih anak untuk bersikap skeptis, selalu membaca isi berita secara utuh, dan tidak langsung membagikan tautan yang belum jelas kebenarannya.'),
  ('13+', 'Diskusi Tantangan Viral (Viral Challenges): Bicarakan bahaya tekanan teman sebaya untuk mengikuti tren atau challenge di TikTok/media sosial yang mengancam keselamatan fisik.'),
  ('13+', 'Kenalkan Konsep Hukum Dasar: Berikan pemahaman ringan bahwa mencemarkan nama baik, mengancam, atau menyebarkan kebencian di internet memiliki konsekuensi hukum (UU ITE).'),
  ('13+', 'Eskalasi Cyberbullying: Dorong anak untuk berani mengambil tangkapan layar (screenshot) sebagai bukti dan segera melapor jika mereka atau temannya menjadi korban perundungan siber.'),
  ('13+', 'Kurangi Pantauan Fisik, Tingkatkan Diskusi: Kurangi mengecek HP secara diam-diam. Ganti pendekatannya dengan menanyakan, ''Ada konten apa yang lagi ramai di internet hari ini?'' secara kasual.'),
  ('17+', 'Audit Jejak Digital Mandiri: Ajak anak untuk ''meng-Google'' nama mereka sendiri dan mendiskusikan bagaimana hasil pencarian tersebut dapat memengaruhi penerimaan universitas atau beasiswa.'),
  ('17+', 'Keamanan Siber Tingkat Lanjut: Wajibkan penggunaan Autentikasi Dua Faktor (2FA) di semua akun utama (email dan media sosial) untuk mencegah peretasan.'),
  ('17+', 'Bahaya Kekerasan Berbasis Gender Online (KBGO): Edukasi mendalam mengenai kejahatan manipulasi identitas, doxing (penyebaran data pribadi), dan balas dendam pornografi (revenge porn).'),
  ('17+', 'Hargai Batasan Privasi: Orang tua tidak boleh lagi meminta kata sandi (password) media sosial anak secara paksa. Bangun kepercayaan berbasis akuntabilitas.'),
  ('17+', 'Diskusi Catfishing & Asmara Online: Buka komunikasi tentang risiko berpacaran dengan seseorang di internet yang identitas aslinya belum tentu sama dengan foto profilnya.'),
  ('17+', 'Literasi Finansial Digital: Edukasi bahaya laten di dunia maya yang berkedok finansial, seperti penipuan lokapasar (e-commerce), phishing, hingga bahaya situs judi/slot online.'),
  ('17+', 'Integritas Akademik & Hak Cipta: Tekankan pentingnya menghindari plagiarisme (termasuk copy-paste langsung dari AI) saat mengerjakan tugas sekolah.'),
  ('17+', 'Keamanan Jaringan Eksternal: Ingatkan bahayanya mengakses akun penting, bertransaksi finansial, atau mengirim dokumen pribadi menggunakan Wi-Fi publik (kafe/sekolah).'),
  ('17+', 'Jadilah Bystander yang Membela: Dorong remaja untuk memiliki empati dengan melaporkan akun pelaku atau memberikan dukungan psikologis langsung kepada teman yang sedang dirundung di internet.'),
  ('17+', 'Sosialisasikan Kanal Bantuan Profesional: Pastikan anak tahu nomor layanan krisis darurat (misalnya SAPA 129 dari KemenPPPA) jika suatu saat mereka menghadapi masalah berat yang takut mereka ceritakan kepada orang tua.'),
  ('PRC', 'Perubahan Peran Pengasuhan: Hentikan segala bentuk pengawasan (monitoring) teknis. Posisikan diri Anda sebagai teman diskusi yang setara.'),
  ('PRC', 'Akuntabilitas Hukum Mutlak: Tegaskan bahwa mereka kini memegang KTP, sehingga setiap pelanggaran siber (penipuan, pencemaran nama baik, penyebaran konten ilegal) akan langsung diproses atas nama mereka sendiri.'),
  ('PRC', 'Pencegahan Pencurian Identitas (Identity Theft): Ingatkan bahaya sembarangan mengunggah foto KTP, KK, atau boarding pass yang rawan disalahgunakan oleh pihak tidak bertanggung jawab.'),
  ('PRC', 'Bahaya Pinjaman Online (Pinjol) Ilegal: Edukasi tentang risiko terjerat layanan finansial ilegal yang sering menyedot kontak HP dan mempermalukan nasabah yang telat membayar.'),
  ('PRC', 'Manajemen Stres & Digital Detox: Dorong anak untuk mengenali batasan mental mereka sendiri dan berani memutuskan koneksi dari internet (detox) jika merasa cemas, depresi, atau burnout.'),
  ('PRC', 'Bangun Personal Branding Profesional: Diskusikan transisi penggunaan internet dari sekadar hiburan menjadi alat membangun portofolio, seperti menggunakan LinkedIn.'),
  ('PRC', 'Regulasi Diri dalam Opini Publik: Ingatkan agar mampu menahan diri (self-regulation) ketika berdebat di ruang publik maya; emosi sesaat dapat merusak karier permanen.'),
  ('PRC', 'Pemahaman Konten Legalitas Orang Dewasa: Berikan diskusi terbuka namun etis mengenai paparan konten dewasa (seperti perjudian atau pornografi), fokus pada dampak psikologis, kecanduan, dan hukumnya.'),
  ('PRC', 'Kemandirian Penyelesaian Masalah: Biarkan mereka menyelesaikan konflik digital mereka sendiri (misal: penipuan transaksi online), namun tetap dampingi secara moral jika mereka meminta nasihat strategis.'),
  ('PRC', 'Akses Bantuan Hukum & Psikologis: Pastikan mereka paham prosedur melaporkan kejahatan siber (ke kepolisian/BSSN) dan tahu cara mencari bantuan psikolog profesional jika menjadi korban eskalasi kejahatan digital berat seperti doxing massal.');
